            req(rv$inputs$data)
            dplyr::mutate(tidyr::pivot_wider(dplyr::mutate(dplyr::summarise(dplyr::group_by(dplyr::filter(rv$inputs$data$chain_summary$resultVariables, 
                .data$active), .data$entity, .data$areaBased), 
                n_var = dplyr::n(), .groups = "drop"), areaBased = dplyr::if_else(.data$areaBased, 
                "areaBased", "notAreaBased")), names_from = .data$areaBased, 
                values_from = .data$n_var), areaBased = dplyr::if_else(is.na(.data$areaBased), 
                0, .data$areaBased), notAreaBased = dplyr::if_else(is.na(.data$notAreaBased), 
