            summary(rv$inputs$data[[input$insight_sel_entity]][, 
                input$insight_sel_vars])
        })
        make_bar_plot <- function(df, x_dim, measure, fill_col, 
            facet_col, show_errbar, dim_meta, measures_meta, 
            extra_filter_vals) {
            for (nm in names(extra_filter_vals)) {
                val <- extra_filter_vals[[nm]]
                if (isTruthy(val) && val != "") {
                  df <- dplyr::filter(df, .data[[nm]] == val)
                }
            }
            use_fill <- isTruthy(fill_col) && fill_col != ""
            use_facet <- isTruthy(facet_col) && facet_col != 
                ""
            low_col <- paste0(measure, "_low")
            upp_col <- paste0(measure, "_upp")
            has_ci <- all(c(low_col, upp_col) %in% names(df))
            get_lbl <- function(meta, col) {
                dplyr::first(dplyr::pull(dplyr::filter(meta, 
                  .data$name == col), "label"))
            }
            x_label <- get_lbl(dim_meta, x_dim)
            y_label <- get_lbl(measures_meta, measure)
            fill_label <- if (use_fill) 
                get_lbl(dim_meta, fill_col)
            else NULL
