            bar_pos <- if (use_fill) 
                dodge
            else "identity"
            base_aes <- if (use_fill) {
                ggplot2::aes(x = .data[[x_dim]], y = .data[[measure]], 
                  fill = .data[[fill_col]])
            }
            else {
                ggplot2::aes(x = .data[[x_dim]], y = .data[[measure]])
            }
            p <- ggplot2::ggplot(df, base_aes) + ggplot2::geom_col(position = bar_pos) + 
