                ggplot2::theme_minimal() + ggplot2::theme(axis.text.x = ggplot2::element_text(angle = 45, 
                hjust = 1))
            if (show_errbar && has_ci) {
                p <- p + ggplot2::geom_errorbar(ggplot2::aes(ymin = .data[[low_col]], 
                  ymax = .data[[upp_col]]), position = bar_pos, 
                  width = 0.2)
            }
            if (use_facet) {
                p <- p + ggplot2::facet_wrap(ggplot2::vars(!!rlang::sym(facet_col)), 
                  labeller = ggplot2::label_value)
            }
            p
        }
        observeEvent(rv$analysis$result, {
            req(rv$analysis$result, rv$analysis$dim_meta, rv$analysis$measures_meta)
            dim_meta <- dplyr::filter(rv$analysis$dim_meta, .data$name %in% 
                rv$analysis$dims)
            dim_choices <- stats::setNames(dim_meta$name, dim_meta$label)
            meas_meta <- rv$analysis$measures_meta
            meas_choices <- stats::setNames(meas_meta$name, meas_meta$label)
            optional_choices <- c(`-- None --` = "", dim_choices)
            updateSelectInput(session, "plot_dim", choices = dim_choices, 
