                return(NULL)
            df <- rv$analysis$result$MEANS
            dim_meta <- rv$analysis$dim_meta
            filter_inputs <- lapply(extra_dims, function(d) {
                lbl <- dplyr::first(dplyr::pull(dplyr::filter(dim_meta, 
                  .data$name == d), "label"))
                vals <- sort(unique(df[[d]]))
                selectInput(inputId = ns(paste0("filter_dim__", 
                  d)), label = paste0("Filter: ", lbl), choices = stats::setNames(vals, 
                  vals), selected = vals[1])
            })
            div(style = "margin-top: 0.75rem; border-top: 1px solid #dee2e6; padding-top: 0.75rem;", 
                tags$small(class = "text-muted", bsicons::bs_icon("funnel"), 
                  " Extra dimension filters"), layout_column_wrap(width = "180px", 
                  fill = FALSE, !!!filter_inputs))
        })
        get_extra_filter_vals <- function() {
            req(rv$analysis$dims, input$plot_dim)
            allocated <- c(input$plot_dim, if (isTruthy(input$plot_fill) && 
                input$plot_fill != "") input$plot_fill else NULL, 
                if (isTruthy(input$plot_facet) && input$plot_facet != 
                  "") input$plot_facet else NULL)
            extra_dims <- setdiff(rv$analysis$dims, allocated)
            vals <- lapply(stats::setNames(extra_dims, extra_dims), 
                function(d) {
                  input[[paste0("filter_dim__", d)]]
                })
            vals
        }
        output$analysis_plot_means <- renderPlot({
            req(rv$analysis$result, input$plot_dim, input$plot_measure)
            make_bar_plot(df = rv$analysis$result$MEANS, x_dim = input$plot_dim, 
                measure = input$plot_measure, fill_col = input$plot_fill, 
                facet_col = input$plot_facet, show_errbar = isTRUE(input$plot_errbar), 
                dim_meta = rv$analysis$dim_meta, measures_meta = rv$analysis$measures_meta, 
                extra_filter_vals = get_extra_filter_vals())
        })
        output$analysis_plot_totals <- renderPlot({
            req(rv$analysis$result, input$plot_dim, input$plot_measure)
            make_bar_plot(df = rv$analysis$result$TOTALS, x_dim = input$plot_dim, 
                measure = input$plot_measure, fill_col = input$plot_fill, 
                facet_col = input$plot_facet, show_errbar = isTRUE(input$plot_errbar), 
                dim_meta = rv$analysis$dim_meta, measures_meta = rv$analysis$measures_meta, 
                extra_filter_vals = get_extra_filter_vals())
        })
        output$vb_seplen_mean <- renderUI({
            fct_mean(.df = rv$ct$user_iris, .colnum = .data$Sepal.Length, 
                .rounding = 1)
        })
        output$vb_sepwid_mean <- renderUI({
            fct_mean(.df = rv$ct$user_iris, .colnum = .data$Sepal.Width, 
                .rounding = 1)
        })
        output$vb_nb_species <- renderUI({
            length(unique(rv$ct$user_iris$Species))
        })
        output$scatter1 <- d3scatter::renderD3scatter({
            d3scatter::d3scatter(rv$ct$shared_iris, ~Petal.Length, 
                ~Petal.Width, ~Species, width = "100%")
        })
        output$scatter2 <- d3scatter::renderD3scatter({
            d3scatter::d3scatter(rv$ct$shared_iris, ~Sepal.Length, 
                ~Sepal.Width, ~Species, width = "100%")
        })
        output$summary <- renderPrint({
            df <- dplyr::mutate(dplyr::filter(rv$ct$shared_iris$data(withSelection = TRUE), 
                .data$selected_ | is.na(.data$selected_)), selected_ = NULL)
            cat(nrow(df), "observation(s) selected\n\n")
            summary(df)
        })
    })
})

